	writeln('tabellina 3');
	i := 1;
	while (i <= 10) do
	begin
		writeln(3 * i);
		inc(i);
	end;
end.

program parametri;
procedure foo(a,b: integer; var c: integer);
{a e b sono parametri valore mentre c è variabile}
begin
	a := a * a;	{modifica locale}
	writeln('local a = ', a);
	b := b * b;	{modifica locale}
	writeln('local b = ', b);
	c := a + b;	{modifica globale}
	writeln('local c = ', c);
end;
var a, b, c: integer;
begin
	a := 10;
	b := 5;
	c := 0;
	foo(a, b, c);
	writeln('global a = ', a);
	writeln('global b = ', b);
	writeln('global c = ', c);
	{
	dopo questa chiamata abbiamo:
	c = 125
	a = 10
	b = 5
	i valori di a e b sono invariati mentre quello di c è stato
	modificato
	}
end.

program subroutine_test;

function somma(a, b: integer): integer;
begin
	somma := a + b;
end;

procedure stampa_somma(a, b: integer);
begin
	writeln(a, ' + ', b, ' = ', a + b);
end;

function sqr(a: integer): integer;
begin
	sqr := a * a;
end;

procedure foo(a,b: integer; var c: integer);
{a e b sono parametri valore mentre c è variabile}
begin
	a := a * a;	{modifica locale}
	b := b * b;	{modifica locale}
	c := a + b;	{modifica globale}
end;

var a, b, n: integer;
begin
	writeln('inserisci due numeri:');
	readln(a, b);
	n := somma(a, b);
	writeln(a, ' + ', b, ' = ', a + b);
	writeln(a, ' + ', b, ' = ', somma(a, b));
	stampa_somma(a, b);
	foo(a, b, n);
	writeln(a, ' ', b,' ', n);
end.

program if_else;
var a,b: integer;
c: char;
begin
	writeln('inserisci due numeri: ');
	readln(a, b);
	if (a < b) then
		writeln(a, ' < ', b)
	else if (a = b) then
		writeln(a, ' = ', b)
	else
		writeln(a, ' > ', b);

	if ('c' < 'd') then
		writeln('ok');
	c := 'c';
	if (false < true) then
		writeln('false < true');

	if (c < 'd') then
		writeln('c < d');
	if (c < 'prova') then
		writeln('c < prova');

	a := 10;
	if (a < 29.2) then
		writeln('10 < 29.2');

	if (ord('c') < 10) then
		writeln('boh');
end.

program formatted_io;
var a1,a2,a3,a4,a5,a6: integer;
begin
	a1 := 10;
	a2 := 334;
	a3 := 2103;
	a4 := 0;
	a5 := 46;
	a6 := 555;
	{testo non formattato}
	writeln('tabella:');
	writeln(a1, ' ', a2, ' ', a3);
	writeln(a4, ' ', a5, ' ', a6);
	writeln;
	{testo formattato}
	writeln('tabella:');
	writeln(a1:6, a2:6, a3:6); {6 colonne per dato}
	writeln(a4:6, a5:6, a6:6);
end.

