program vettori;
var a,b: array [1..10] of integer;
	i: integer;
begin
	randomize;
	for i := 1 to 10 do begin
		a[i] := random(100);
		writeln('a[',i,'] = ',a[i]);
	end;
	b := a;
	for i := 1 to 10 do a[i] := 0;
	writeln;
	for i := 1 to 10 do
		writeln('a[', i,'] = ', a[i]);
	writeln;
	for i := 1 to 10 do
		writeln('b[', i,'] = ', b[i]);
end.

program vettori_multi;
const
	n = 10;
	p=10;
var
	m : array[1..n, 1..p] of integer;
	i,j: integer;
begin
	randomize;
	for i := 1 to p do begin
		for j := 1 to n do begin
			m[i,j] := random(100)+1;
			write(m[i,j]:4);
		end;
		writeln;
	end;
end.

